using McpHttpServer.Tools;
using ModelContextProtocol;
using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithResources();

var app = builder.Build();

// Map the MCP endpoint at /mcp (handles both SSE and Streamable HTTP)
app.MapMcp();

app.Run();

// Resource provider that exposes configuration data
[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings",
        Name = "App Settings",
        Description = "Returns application configuration data")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            Features = new { EnableLogging = true, MaxRetries = 3 }
        };

        return System.Text.Json.JsonSerializer.Serialize(config,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/endpoints",
        Name = "API Endpoints",
        Description = "Returns available API endpoint configuration")]
    public static string GetEndpoints()
    {
        var endpoints = new
        {
            HealthCheck = "/health",
            Mcp = "/mcp",
            Docs = "/docs"
        };

        return System.Text.Json.JsonSerializer.Serialize(endpoints,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

